package com.scale.workercapture;
import android.content.*;import java.io.*;import java.util.*;import java.util.zip.*;
public class ZipExporter {
 public static File make(Context c, ArrayList<MainActivity.Worker> ws)throws Exception{ArrayList<MainActivity.Worker> complete=new ArrayList<>();for(MainActivity.Worker w:ws)if(w.workerPath!=null&&!w.workerPath.isEmpty()&&w.handPath!=null&&!w.handPath.isEmpty())complete.add(w);if(complete.isEmpty())return null;File out=new File(c.getExternalFilesDir(null),"workers-"+new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())+".zip");ZipOutputStream z=new ZipOutputStream(new FileOutputStream(out));StringBuilder json=new StringBuilder("[\n");for(int i=0;i<complete.size();i++){MainActivity.Worker w=complete.get(i);String n=String.valueOf(i+1);add(z,n+"/worker.jpg",new File(w.workerPath));add(z,n+"/hand.jpg",new File(w.handPath));json.append("  {\"name\":\"").append(esc(w.name)).append("\",\"deviceID\":\"").append(w.deviceId).append("\",\"workerPhoto\":\"").append(n).append("/worker.jpg\",\"hand\":\"").append(n).append("/hand.jpg\"}");if(i+1<complete.size())json.append(',');json.append('\n');}json.append("]\n");z.putNextEntry(new ZipEntry("workers.json"));z.write(json.toString().getBytes("UTF-8"));z.closeEntry();z.close();return out;}
 static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}static void add(ZipOutputStream z,String name,File f)throws Exception{z.putNextEntry(new ZipEntry(name));FileInputStream in=new FileInputStream(f);byte[] b=new byte[8192];int n;while((n=in.read(b))>0)z.write(b,0,n);in.close();z.closeEntry();}
}
